type Role = 'client' | 'admin' | null;
type User = { name: string; phone: string; role: Role };

const usePersistentState = <T,>(key: string, fallback: T) => {
  const [value, setValue] = useState<T>(() => {
    try {
      const stored = localStorage.getItem(key);
      return stored ? JSON.parse(stored) as T : fallback;
    } catch { return fallback; }
  });
  const update = (next: T | ((current: T) => T)) => {
    setValue((current) => {
      const resolved = typeof next === 'function' ? (next as (current: T) => T)(current) : next;
      localStorage.setItem(key, JSON.stringify(resolved));
      return resolved;
    });
  };
  return [value, update] as const;
};

type AppContextValue = {
  cart: CartLine[]; setCart: (next: CartLine[] | ((v: CartLine[]) => CartLine[])) => void;
  orders: Order[]; setOrders: (next: Order[] | ((v: Order[]) => Order[])) => void;
  deliveries: Delivery[]; setDeliveries: (next: Delivery[] | ((v: Delivery[]) => Delivery[])) => void;
  rentals: Rental[]; setRentals: (next: Rental[] | ((v: Rental[]) => Rental[])) => void;
  customers: Customer[]; setCustomers: (next: Customer[] | ((v: Customer[]) => Customer[])) => void;
  promotions: Promotion[]; setPromotions: (next: Promotion[] | ((v: Promotion[]) => Promotion[])) => void;
  user: User; setUser: (user: User) => void;
  addToCart: (productId: string, quantity?: number) => void;
  cartCount: number;
};

const AppContext = createContext<AppContextValue | null>(null);
const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('App context missing');
  return context;
};

function AppProvider({ children }: { children: ReactNode }) {
  const [cart, setCart] = usePersistentState<CartLine[]>('tralogistique-cart', []);
  const [orders, setOrders] = usePersistentState<Order[]>('tralogistique-orders', initialOrders);
  const [deliveries, setDeliveries] = usePersistentState<Delivery[]>('tralogistique-deliveries', initialDeliveries);
  const [rentals, setRentals] = usePersistentState<Rental[]>('tralogistique-rentals', initialRentals);
  const [customers, setCustomers] = usePersistentState<Customer[]>('tralogistique-customers', initialCustomers);
  const [promotions, setPromotions] = usePersistentState<Promotion[]>('tralogistique-promotions', initialPromotions);
  const [user, setUserState] = usePersistentState<User>('tralogistique-user', { name: '', phone: '', role: null });
  const addToCart = (productId: string, quantity = 1) => setCart((current) => {
    const existing = current.find((line) => line.productId === productId);
    return existing
      ? current.map((line) => line.productId === productId ? { ...line, quantity: line.quantity + quantity } : line)
      : [...current, { productId, quantity }];
  });
  return <AppContext.Provider value={{
    cart, setCart, orders, setOrders, deliveries, setDeliveries, rentals, setRentals,
    customers, setCustomers, promotions, setPromotions, user, setUser: setUserState,
    addToCart, cartCount: cart.reduce((sum, line) => sum + line.quantity, 0),
  }}>{children}</AppContext.Provider>;
}

const cx = (...classes: Array<string | false | undefined>) => classes.filter(Boolean).join(' ');
const exportLocalFile = (filename: string, payload: unknown) => {
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
};
