function ProductCard({ product, compact = false }: { product: Product; compact?: boolean }) {
  const { addToCart } = useApp();
  const [added, setAdded] = useState(false);
  const price = product.promotion ? product.price * (1 - product.promotion / 100) : product.price;
  return <article className={cx('group overflow-hidden rounded-2xl border border-border bg-card shadow-xs transition duration-300 hover:-translate-y-1 hover:shadow-md', compact && 'flex items-center gap-3 border-0 bg-transparent shadow-none hover:translate-y-0')} data-testid={`card-product-${product.id}`}>
    <Link href={`/produit/${product.id}`} className={cx('block', compact && 'shrink-0')} data-testid={`link-product-${product.id}`}><Visual type={product.image} className={cx(compact ? 'size-20 rounded-xl' : 'h-32 sm:h-36', 'transition duration-500 group-hover:scale-[1.03]')} /></Link>
    <div className={cx('p-4', compact && 'p-0')}><div className="mb-3 flex items-start justify-between gap-2"><span className="text-[10px] font-bold uppercase tracking-[.13em] text-muted-foreground">{product.category}</span>{product.promotion && <span className="rounded-full bg-accent/15 px-2 py-1 text-[10px] font-bold text-accent">-{product.promotion}%</span>}</div><Link href={`/produit/${product.id}`} className="font-display font-bold leading-snug hover:text-primary" data-testid={`text-product-name-${product.id}`}>{product.name}</Link><div className="mt-1 flex items-center gap-2 text-xs text-muted-foreground"><span>{product.unit}</span><span className="size-1 rounded-full bg-secondary" /><span className={product.availability ? 'text-primary' : 'text-destructive'}>{product.availability ? 'En stock' : 'Indisponible'}</span></div><div className="mt-4 flex items-center justify-between gap-2"><div><span className="font-display text-lg font-bold">{formatFcfa(price)}</span>{product.promotion && <span className="ml-1.5 text-xs text-muted-foreground line-through">{formatFcfa(product.price)}</span>}</div>{!compact && <Button onClick={() => { addToCart(product.id); setAdded(true); setTimeout(() => setAdded(false), 1400); }} disabled={!product.availability} className="size-9 rounded-xl px-0" aria-label={`Ajouter ${product.name}`} data-testid={`button-add-${product.id}`}>{added ? <Check className="size-4" /> : <Plus className="size-4" />}</Button>}</div></div>
  </article>;
}

function VehicleCard({ vehicle }: { vehicle: Vehicle }) {
  return <article className="group overflow-hidden rounded-2xl border border-border bg-card shadow-xs transition duration-300 hover:-translate-y-1 hover:shadow-md" data-testid={`card-vehicle-${vehicle.id}`}><Link href={`/location/${vehicle.id}`} data-testid={`link-vehicle-${vehicle.id}`}><Visual type={vehicle.images[0].replace('-1', '')} vehicle className="h-44 sm:h-52 transition duration-500 group-hover:scale-[1.02]" /></Link><div className="p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.12em] text-muted-foreground">{vehicle.category} · {vehicle.year}</p><Link href={`/location/${vehicle.id}`} className="mt-1 block font-display text-xl font-bold hover:text-primary">{vehicle.brand} {vehicle.model}</Link></div><span className={cx('rounded-full px-2.5 py-1 text-[10px] font-bold', vehicle.availability ? 'bg-primary/10 text-primary' : 'bg-muted text-muted-foreground')}>{vehicle.availability ? 'Disponible' : 'Indisponible'}</span></div><div className="mt-4 flex flex-wrap gap-2 text-xs text-muted-foreground"><span className="rounded-md bg-muted px-2 py-1">{vehicle.seats} places</span><span className="rounded-md bg-muted px-2 py-1">{vehicle.transmission}</span><span className="rounded-md bg-muted px-2 py-1">{vehicle.airConditioning ? 'Climatisée' : 'Sans clim.'}</span></div><div className="mt-5 flex items-end justify-between gap-3"><div><span className="font-display text-lg font-bold">{formatFcfa(vehicle.pricePerDay)}</span><span className="text-xs text-muted-foreground"> / jour</span></div><div className="flex items-center gap-3"><Link href={`/location/${vehicle.id}`} className="text-xs font-bold text-primary">Voir <ArrowUpRight className="ml-1 inline size-3.5" /></Link><Link href={vehicle.availability ? `/reservation?vehicle=${vehicle.id}` : `/location/${vehicle.id}`} className={cx('rounded-lg px-3 py-2 text-xs font-bold', vehicle.availability ? 'bg-secondary text-secondary-foreground' : 'border border-border text-muted-foreground')} data-testid={`link-reserve-${vehicle.id}`}>{vehicle.availability ? 'Réserver' : 'Détails'}</Link></div></div></div></article>;
}

function HomePage() {
  return <PublicShell><section className="relative overflow-hidden bg-primary text-primary-foreground"><div className="absolute right-[-12%] top-[-25%] size-[520px] rounded-full border-[70px] border-secondary/15" /><div className="absolute bottom-[-20%] left-[33%] size-[330px] rounded-full border-[50px] border-accent/15" /><div className="mx-auto grid max-w-[1240px] gap-10 px-5 pb-16 pt-14 lg:grid-cols-[1.02fr_.98fr] lg:items-center lg:px-8 lg:pb-24 lg:pt-24"><div className="relative z-10 animate-rise"><p className="mb-6 inline-flex items-center gap-2 rounded-full border border-primary-foreground/20 bg-primary-foreground/10 px-3 py-1.5 text-xs font-bold tracking-wide text-secondary"><span className="size-1.5 rounded-full bg-secondary" /> Dakar · Opérations du jour</p><h1 className="max-w-xl font-display text-5xl font-bold leading-[.98] tracking-[-.055em] md:text-7xl">Le local,<br /><span className="text-secondary">bien orchestré.</span></h1><p className="mt-7 max-w-lg text-base leading-7 text-primary-foreground/70 md:text-lg">Courses utiles, livraisons qui tiennent parole, voitures prêtes à partir. Une seule équipe pour faire avancer vos journées à Dakar.</p><div className="mt-9 flex flex-col gap-3 sm:flex-row"><Link href="/boutique" className="inline-flex items-center justify-center gap-2 rounded-xl bg-secondary px-5 py-3.5 text-sm font-bold text-secondary-foreground shadow-lg transition hover:-translate-y-1 hover:shadow-xl">Découvrir la boutique <ArrowRight className="size-4" /></Link><Link href="/location" className="inline-flex items-center justify-center gap-2 rounded-xl border border-primary-foreground/20 px-5 py-3.5 text-sm font-bold transition hover:bg-primary-foreground/10">Louer un véhicule</Link></div><div className="mt-10 flex items-center gap-6 text-sm text-primary-foreground/55"><span className="flex items-center gap-2"><Check className="size-4 text-secondary" /> Paiement à la livraison</span><span className="hidden items-center gap-2 sm:flex"><Check className="size-4 text-secondary" /> Équipe locale</span></div></div><div className="relative min-h-[370px] animate-rise delay-2"><div className="absolute left-[7%] top-[4%] h-[84%] w-[81%] rotate-[-6deg] rounded-[2.5rem] bg-secondary/90 p-4 shadow-2xl"><div className="flex h-full flex-col justify-between overflow-hidden rounded-[1.8rem] bg-[#f1dec0] p-6 text-primary"><div className="flex justify-between text-xs font-bold uppercase tracking-[.16em]"><span>La sélection</span><span>14.08.25</span></div><div><span className="block font-display text-[100px] font-bold leading-[.75] tracking-[-.1em] opacity-80">T.</span><p className="mt-5 max-w-[190px] font-display text-2xl font-bold leading-tight">Un panier qui raconte quelque chose.</p></div><div className="flex items-end justify-between"><span className="text-xs font-semibold">Livré à Dakar<br />avec soin</span><div className="grid size-12 place-items-center rounded-full bg-primary text-secondary"><ArrowUpRight className="size-5" /></div></div></div></div><div className="absolute bottom-0 right-0 w-[52%] rotate-[8deg] overflow-hidden rounded-3xl border-8 border-primary shadow-xl"><Visual type="basket" className="h-48" /></div><div className="absolute right-[2%] top-[10%] flex items-center gap-2 rounded-full bg-card px-3 py-2 text-xs font-bold text-foreground shadow-lg"><span className="grid size-6 place-items-center rounded-full bg-secondary text-secondary-foreground"><Check className="size-3.5" /></span> Arrivé à l’heure</div></div></div></section>
     <section className="mx-auto max-w-[1240px] px-5 py-16 lg:px-8 lg:py-24"><div className="grid gap-8 md:grid-cols-3"><div className="rounded-2xl bg-secondary p-7 text-secondary-foreground animate-rise"><p className="text-xs font-bold uppercase tracking-[.16em]">01 · À manger</p><h2 className="mt-9 font-display text-3xl font-bold leading-tight">Les bons essentiels,<br />sans détour.</h2><Link href="/boutique" className="mt-10 inline-flex items-center gap-2 text-sm font-bold underline decoration-2 underline-offset-4">Entrer dans la boutique <ArrowUpRight className="size-4" /></Link></div><div className="rounded-2xl bg-accent p-7 text-accent-foreground animate-rise delay-1"><p className="text-xs font-bold uppercase tracking-[.16em]">02 · À bouger</p><h2 className="mt-9 font-display text-3xl font-bold leading-tight">Une voiture nette.<br />Un départ simple.</h2><Link href="/location" className="mt-10 inline-flex items-center gap-2 text-sm font-bold underline decoration-2 underline-offset-4">Voir les véhicules <ArrowUpRight className="size-4" /></Link></div><div className="rounded-2xl bg-muted p-7 animate-rise delay-2"><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">03 · À livrer</p><h2 className="mt-9 font-display text-3xl font-bold leading-tight">On coordonne.<br />Vous respirez.</h2><Link href="/livraison" className="mt-10 inline-flex items-center gap-2 text-sm font-bold text-primary underline decoration-2 underline-offset-4">Découvrir la livraison <ArrowUpRight className="size-4" /></Link></div></div></section>
     <section className="border-b border-border bg-background"><div className="mx-auto max-w-[1240px] px-5 py-12 lg:px-8"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">La suite se prépare</p><h2 className="mt-3 font-display text-3xl font-bold tracking-tight">Une même maison,<br className="sm:hidden" /> de nouveaux relais.</h2></div><p className="max-w-md text-sm leading-6 text-muted-foreground">Vente de véhicules, pièces de rechange et import-export arrivent progressivement. Chaque activité aura son espace, ses règles et son équipe.</p></div><div className="mt-8 grid gap-3 sm:grid-cols-3"><Link href="/vente-vehicules" className="group rounded-2xl border border-border bg-card p-5 transition hover:-translate-y-1 hover:border-primary/40"><CarFront className="size-5 text-primary" /><div className="mt-8 flex items-end justify-between gap-3"><span><span className="block font-display font-bold">Vente de véhicules</span><span className="mt-1 block text-xs text-muted-foreground">Bientôt disponible</span></span><ArrowUpRight className="size-4 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-primary" /></div></Link><Link href="/pieces-rechange" className="group rounded-2xl border border-border bg-card p-5 transition hover:-translate-y-1 hover:border-primary/40"><Wrench className="size-5 text-primary" /><div className="mt-8 flex items-end justify-between gap-3"><span><span className="block font-display font-bold">Pièces de rechange</span><span className="mt-1 block text-xs text-muted-foreground">Bientôt disponible</span></span><ArrowUpRight className="size-4 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-primary" /></div></Link><Link href="/import-export" className="group rounded-2xl border border-border bg-card p-5 transition hover:-translate-y-1 hover:border-primary/40"><RouteIcon className="size-5 text-primary" /><div className="mt-8 flex items-end justify-between gap-3"><span><span className="block font-display font-bold">Import-export</span><span className="mt-1 block text-xs text-muted-foreground">En préparation</span></span><ArrowUpRight className="size-4 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-primary" /></div></Link></div></div></section>
    <section className="border-y border-border bg-card"><div className="mx-auto grid max-w-[1240px] gap-10 px-5 py-16 lg:grid-cols-[.8fr_1.2fr] lg:px-8 lg:py-24"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Cette semaine</p><h2 className="mt-3 font-display text-4xl font-bold tracking-tight">Les préférés<br />de la maison.</h2><p className="mt-4 max-w-sm text-sm leading-6 text-muted-foreground">Des produits choisis pour leur origine, leur goût et la facilité qu’ils apportent au quotidien.</p><Link href="/boutique" className="mt-7 inline-flex items-center gap-2 text-sm font-bold text-primary">Voir toute la sélection <ArrowRight className="size-4" /></Link></div><div className="grid grid-cols-2 gap-3 md:grid-cols-4">{products.slice(0, 4).map((product, index) => <div key={product.id} className={cx(index === 0 && 'col-span-2 md:col-span-1')}><ProductCard product={product} /></div>)}</div></div></section>
    <section className="mx-auto max-w-[1240px] px-5 py-16 lg:px-8 lg:py-24"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Mobilité</p><h2 className="mt-3 font-display text-4xl font-bold tracking-tight">Prêt quand vous l’êtes.</h2></div><Link href="/location" className="text-sm font-bold text-primary">Tout le parc <ArrowRight className="ml-1 inline size-4" /></Link></div><div className="mt-8 grid gap-5 md:grid-cols-3">{vehicles.slice(0, 3).map((vehicle) => <VehicleCard key={vehicle.id} vehicle={vehicle} />)}</div></section>
    <section className="bg-[#eadfce]"><div className="mx-auto max-w-[1240px] px-5 py-16 lg:px-8 lg:py-24"><div className="grid gap-8 lg:grid-cols-[.8fr_1.2fr]"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">La promesse</p><h2 className="mt-3 font-display text-4xl font-bold leading-tight tracking-tight">Pas de flou.<br />Juste le prochain geste.</h2></div><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-background p-6"><Clock3 className="size-6 text-primary" /><h3 className="mt-7 font-display text-xl font-bold">Des horaires tenus</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Vous savez où en est votre commande, de la préparation à votre porte.</p></div><div className="rounded-2xl bg-background p-6"><Headphones className="size-6 text-primary" /><h3 className="mt-7 font-display text-xl font-bold">Une vraie équipe</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Une question ? Une personne vous répond, pas une boucle automatique.</p></div><div className="rounded-2xl bg-background p-6"><Wallet className="size-6 text-primary" /><h3 className="mt-7 font-display text-xl font-bold">Des prix lisibles</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Le détail de votre total est clair avant de confirmer.</p></div><div className="rounded-2xl bg-background p-6"><MapPin className="size-6 text-primary" /><h3 className="mt-7 font-display text-xl font-bold">Dakar, au détail près</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Nous connaissons les quartiers, les détours et les bons créneaux.</p></div></div></div></div></section>
    <section className="mx-auto max-w-[1240px] px-5 py-16 lg:px-8 lg:py-24"><div className="grid gap-6 md:grid-cols-3"><Testimonial quote="J’ai commandé le panier Teranga pour un cadeau. Tout était bien emballé, et livré comme annoncé." name="Awa Ndiaye" meta="Mermoz, Dakar" /><Testimonial quote="La Corolla était propre et prête à l’heure. J’ai apprécié les conditions expliquées sans surprise." name="Ibrahima Ba" meta="Ouakam, Dakar" /><Testimonial quote="Enfin un service où on peut écrire sur WhatsApp et avoir une réponse claire. Ça change tout." name="Fatou Sarr" meta="Almadies, Dakar" /></div></section>
    <section className="mx-auto max-w-[1240px] px-5 pb-20 lg:px-8"><div className="flex flex-col items-start justify-between gap-8 rounded-[2rem] bg-primary px-7 py-10 text-primary-foreground md:flex-row md:items-center md:px-12"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-secondary">On se parle ?</p><h2 className="mt-3 font-display text-3xl font-bold">Votre prochain trajet commence ici.</h2></div><div className="flex flex-wrap gap-3"><a href="https://wa.me/221772341860" target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-xl bg-secondary px-5 py-3 text-sm font-bold text-secondary-foreground"><MessageCircle className="size-4" /> WhatsApp</a><a href="tel:+221772341860" className="inline-flex items-center gap-2 rounded-xl border border-primary-foreground/20 px-5 py-3 text-sm font-bold"><Phone className="size-4" /> Appeler</a></div></div></section>
  </PublicShell>;
}
function Testimonial({ quote, name, meta }: { quote: string; name: string; meta: string }) { return <div className="rounded-2xl border border-border bg-card p-6"><div className="flex gap-1 text-secondary">{[1, 2, 3, 4, 5].map((star) => <Star key={star} className="size-3.5 fill-current" />)}</div><p className="mt-5 text-sm leading-6">“{quote}”</p><div className="mt-6 border-t border-border pt-4"><p className="text-sm font-bold">{name}</p><p className="text-xs text-muted-foreground">{meta}</p></div></div>; }

function BoutiquePage() {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState('Toutes'); const [sort, setSort] = useState('popular');
  const categories = ['Toutes', ...Array.from(new Set(products.map((product) => product.category)))];
  const filtered = useMemo(() => products.filter((product) => (category === 'Toutes' || product.category === category) && `${product.name} ${product.description}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sort === 'price' ? a.price - b.price : sort === 'name' ? a.name.localeCompare(b.name) : Number(Boolean(b.promotion)) - Number(Boolean(a.promotion))), [category, query, sort]);
  return <PublicShell><div className="mx-auto max-w-[1240px] px-5 py-12 lg:px-8 lg:py-16"><PageIntro eyebrow="La boutique" title="Le garde-manger, version locale." description="Une sélection courte et bien choisie, livrée à Dakar. Prix affichés en FCFA, paiement simulé à la commande." action={<Link href="/panier" className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-bold"><ShoppingCart className="size-4" /> Voir le panier</Link>} /><div className="mb-8 grid gap-3 md:grid-cols-[1fr_auto_auto]"><label className="relative block"><Search className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Rechercher un produit..." className="h-11 w-full rounded-xl border border-input bg-card pl-10 pr-4 text-sm outline-none focus:border-primary" data-testid="input-product-search" /></label><select value={category} onChange={(event) => setCategory(event.target.value)} className="h-11 rounded-xl border border-input bg-card px-3 text-sm font-semibold outline-none" data-testid="select-product-category">{categories.map((item) => <option key={item}>{item}</option>)}</select><select value={sort} onChange={(event) => setSort(event.target.value)} className="h-11 rounded-xl border border-input bg-card px-3 text-sm font-semibold outline-none" data-testid="select-product-sort"><option value="popular">À la une</option><option value="price">Prix croissant</option><option value="name">Nom</option></select></div>{filtered.length ? <div className="grid grid-cols-2 gap-3 md:grid-cols-3 lg:grid-cols-4 lg:gap-5">{filtered.map((product, index) => <div key={product.id} className={cx('animate-rise', `delay-${Math.min(index + 1, 5)}`)}><ProductCard product={product} /></div>)}</div> : <EmptyState title="Aucun produit trouvé" description="Essayez un autre mot ou revenez à toutes les catégories." icon={Search} />}</div></PublicShell>;
}

function ProductPage() {
  const { id } = useParams<{ id: string }>(); const product = getProduct(id || ''); const { addToCart } = useApp(); const [, setLocation] = useLocation(); const [quantity, setQuantity] = useState(1); const [added, setAdded] = useState(false);
  if (!product) return <NotFound />;
  const price = product.promotion ? product.price * (1 - product.promotion / 100) : product.price;
  return <PublicShell><div className="mx-auto max-w-[1100px] px-5 py-10 lg:px-8 lg:py-16"><Link href="/boutique" className="mb-8 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-primary"><ArrowLeft className="size-4" /> Retour à la boutique</Link><div className="grid gap-10 md:grid-cols-[.95fr_1.05fr] md:items-center"><div className="overflow-hidden rounded-[2rem] border border-border bg-card p-2 shadow-sm"><Visual type={product.image} className="aspect-[4/3] w-full rounded-[1.5rem]" /></div><div><div className="flex items-center gap-3"><span className="text-xs font-bold uppercase tracking-[.17em] text-accent">{product.category}</span>{product.promotion && <span className="rounded-full bg-accent/15 px-2.5 py-1 text-xs font-bold text-accent">-{product.promotion}% aujourd’hui</span>}</div><h1 className="mt-4 max-w-lg font-display text-4xl font-bold tracking-tight md:text-5xl">{product.name}</h1><p className="mt-3 text-sm text-muted-foreground">{product.unit} · {product.stock} en stock</p><p className="mt-7 max-w-xl text-base leading-7 text-muted-foreground">{product.description}</p><div className="mt-8 flex items-end gap-3"><span className="font-display text-3xl font-bold">{formatFcfa(price)}</span>{product.promotion && <span className="mb-1 text-sm text-muted-foreground line-through">{formatFcfa(product.price)}</span>}</div><div className="mt-8 flex flex-wrap items-center gap-3"><div className="flex h-12 items-center rounded-xl border border-border bg-card"><button onClick={() => setQuantity((value) => Math.max(1, value - 1))} className="grid size-11 place-items-center text-lg" data-testid="button-decrease-quantity">−</button><span className="w-8 text-center font-bold" data-testid="text-product-quantity">{quantity}</span><button onClick={() => setQuantity((value) => Math.min(product.stock, value + 1))} className="grid size-11 place-items-center text-lg" data-testid="button-increase-quantity">+</button></div><Button onClick={() => { addToCart(product.id, quantity); setAdded(true); setTimeout(() => setAdded(false), 1600); }} disabled={!product.availability} className="h-12 px-6" data-testid="button-add-to-cart">{added ? <><Check className="size-4" /> Ajouté au panier</> : <><ShoppingCart className="size-4" /> Ajouter au panier</>}</Button>{added && <button onClick={() => setLocation('/panier')} className="text-sm font-bold text-primary underline underline-offset-4">Voir le panier</button>}</div><div className="mt-10 grid gap-3 border-t border-border pt-6 text-sm sm:grid-cols-2"><div className="flex gap-3"><Truck className="size-5 text-primary" /><span><b className="block">Livraison à Dakar</b><small className="text-muted-foreground">À partir de 2 000 FCFA</small></span></div><div className="flex gap-3"><Wallet className="size-5 text-primary" /><span><b className="block">Paiement simulé</b><small className="text-muted-foreground">Wave, Orange Money ou espèces</small></span></div></div></div></div><section className="mt-20 border-t border-border pt-12"><h2 className="font-display text-2xl font-bold">Vous aimerez aussi</h2><div className="mt-6 grid grid-cols-2 gap-3 md:grid-cols-4">{products.filter((item) => item.id !== product.id).slice(0, 4).map((item) => <ProductCard key={item.id} product={item} />)}</div></section></div></PublicShell>;
}

function CartPage() {
  const { cart, setCart } = useApp(); const [, setLocation] = useLocation();
  const lines = cart.map((line) => ({ ...line, product: getProduct(line.productId) })).filter((line): line is CartLine & { product: Product } => Boolean(line.product));
  const subtotal = lines.reduce((sum, line) => sum + (line.product.promotion ? line.product.price * (1 - line.product.promotion / 100) : line.product.price) * line.quantity, 0);
  const delivery = lines.length ? 2000 : 0; const total = subtotal + delivery;
  const changeQuantity = (id: string, quantity: number) => setCart((current) => quantity <= 0 ? current.filter((line) => line.productId !== id) : current.map((line) => line.productId === id ? { ...line, quantity } : line));
  return <PublicShell><div className="mx-auto max-w-[1080px] px-5 py-12 lg:px-8 lg:py-16"><PageIntro eyebrow="Votre commande" title="Le panier, avant le départ." description="Relisez vos articles, ajustez les quantités, puis indiquez-nous où vous livrer." />{lines.length ? <div className="grid gap-8 lg:grid-cols-[1fr_360px]"><div className="rounded-2xl border border-border bg-card p-4 sm:p-6"><div className="mb-3 flex justify-between border-b border-border pb-4 text-xs font-bold uppercase tracking-[.14em] text-muted-foreground"><span>{lines.length} article{lines.length > 1 ? 's' : ''}</span><span>Prix unitaire</span></div><div className="divide-y divide-border">{lines.map(({ product, quantity }) => { const price = product.promotion ? product.price * (1 - product.promotion / 100) : product.price; return <div key={product.id} className="flex gap-3 py-5 sm:gap-5"><Visual type={product.image} className="size-20 shrink-0 rounded-xl sm:size-24" /><div className="min-w-0 flex-1"><div className="flex justify-between gap-3"><div><Link href={`/produit/${product.id}`} className="font-display font-bold hover:text-primary">{product.name}</Link><p className="mt-1 text-xs text-muted-foreground">{product.unit}</p></div><button onClick={() => changeQuantity(product.id, 0)} className="text-muted-foreground hover:text-destructive" aria-label={`Supprimer ${product.name}`} data-testid={`button-remove-${product.id}`}><Trash2 className="size-4" /></button></div><div className="mt-4 flex items-center justify-between"><div className="flex h-9 items-center rounded-lg border border-border"><button onClick={() => changeQuantity(product.id, quantity - 1)} className="grid size-8 place-items-center" data-testid={`button-minus-${product.id}`}>−</button><span className="w-7 text-center text-sm font-bold">{quantity}</span><button onClick={() => changeQuantity(product.id, quantity + 1)} className="grid size-8 place-items-center" data-testid={`button-plus-${product.id}`}>+</button></div><span className="font-display font-bold">{formatFcfa(price * quantity)}</span></div></div></div>; })}</div></div><aside className="h-fit rounded-2xl bg-primary p-6 text-primary-foreground lg:sticky lg:top-24"><p className="text-xs font-bold uppercase tracking-[.16em] text-secondary">Récapitulatif</p><div className="mt-7 grid gap-4 text-sm"><div className="flex justify-between text-primary-foreground/70"><span>Sous-total</span><span>{formatFcfa(subtotal)}</span></div><div className="flex justify-between text-primary-foreground/70"><span>Livraison Dakar</span><span>{formatFcfa(delivery)}</span></div><div className="my-1 border-t border-primary-foreground/15" /><div className="flex justify-between text-base font-bold"><span>Total</span><span>{formatFcfa(total)}</span></div></div><Button onClick={() => setLocation('/commande')} className="mt-7 w-full bg-secondary text-secondary-foreground hover:bg-secondary/90" data-testid="button-checkout">Continuer vers la commande <ArrowRight className="size-4" /></Button><p className="mt-4 text-center text-[11px] leading-5 text-primary-foreground/50">Paiement simulé · aucune transaction ne sera débitée</p></aside></div> : <EmptyState title="Votre panier est léger" description="Ajoutez quelques essentiels de la boutique, puis nous les préparons pour vous." icon={ShoppingCart} />}</div></PublicShell>;
}

function CheckoutPage() {
  const { cart, setCart, setOrders, setDeliveries, user, setUser } = useApp(); const [, setLocation] = useLocation(); const [done, setDone] = useState<string | null>(null);
  const lines = cart.map((line) => ({ ...line, product: getProduct(line.productId) })).filter((line): line is CartLine & { product: Product } => Boolean(line.product));
  const subtotal = lines.reduce((sum, line) => sum + (line.product?.promotion ? line.product.price * (1 - line.product.promotion / 100) : line.product.price) * line.quantity, 0); const total = subtotal + (lines.length ? 2000 : 0);
  if (!lines.length && !done) return <PublicShell><div className="mx-auto max-w-[700px] px-5 py-20"><EmptyState title="Rien à commander pour le moment" description="Votre panier est vide. Revenez à la boutique pour commencer." icon={ShoppingCart} /></div></PublicShell>;
  if (done) return <PublicShell><Confirmation title="Commande confirmée" number={done} description="Votre commande est entre de bonnes mains. Nous vous contacterons sur WhatsApp lorsque le livreur prendra la route." href="/boutique" action="Continuer mes achats" /></PublicShell>;
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const name = String(data.get('name')); const phone = String(data.get('phone')); const address = String(data.get('address')); const neighborhood = String(data.get('neighborhood')); const city = String(data.get('city')); const payment = String(data.get('payment')); const id = `TR-${Math.floor(2409 + Math.random() * 500)}`; const order: Order = { id, customer: name, phone, address, neighborhood, city, items: lines.map(({ product, quantity }) => ({ productId: product.id, name: product.name, quantity, price: product.promotion ? product.price * (1 - product.promotion / 100) : product.price, unit: product.unit })), total, deliveryFee: 2000, payment, status: 'En préparation', date: 'À l’instant' }; setOrders((current) => [order, ...current]); setDeliveries((current) => [{ id: `DL-${Math.floor(900 + Math.random() * 80)}`, orderId: id, customer: name, address: `${address}, ${neighborhood}, ${city}`, phone, fee: 2000, status: 'À préparer' }, ...current]); setCart([]); setUser({ name, phone, role: user.role || 'client' }); setDone(id); };
  return <PublicShell><div className="mx-auto max-w-[1100px] px-5 py-12 lg:px-8 lg:py-16"><PageIntro eyebrow="Dernière étape" title="Où devons-nous déposer ça ?" description="Le paiement est simulé : choisissez simplement votre moyen préféré pour finaliser la demande." /><form onSubmit={submit} className="grid gap-8 lg:grid-cols-[1fr_340px]"><div className="rounded-2xl border border-border bg-card p-5 sm:p-7"><h2 className="font-display text-xl font-bold">Vos coordonnées</h2><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Nom complet" name="name" placeholder="Ex. Awa Ndiaye" required defaultValue={user.name} data-testid="input-checkout-name" /><Field label="Téléphone" name="phone" placeholder="77 000 00 00" required defaultValue={user.phone} data-testid="input-checkout-phone" /><Field label="Adresse de livraison" name="address" placeholder="Rue, villa, repère..." required className="sm:col-span-2" data-testid="input-checkout-address" /><Field label="Quartier" name="neighborhood" placeholder="Mermoz, Almadies..." required data-testid="input-checkout-neighborhood" /><Field label="Ville" name="city" defaultValue="Dakar" required data-testid="input-checkout-city" /><label className="grid gap-2 text-sm font-semibold sm:col-span-2">Information complémentaire<textarea name="extra" placeholder="Code, étage, indication pour le livreur..." className="min-h-24 resize-y rounded-xl border border-input bg-background px-3.5 py-3 font-normal outline-none focus:border-primary" data-testid="input-checkout-extra" /></label></div><div className="mt-9 border-t border-border pt-7"><h2 className="font-display text-xl font-bold">Mode de paiement</h2><div className="mt-5 grid gap-3 sm:grid-cols-3">{['Espèces', 'Wave', 'Orange Money'].map((method, index) => <label key={method} className="relative"><input type="radio" name="payment" value={method} defaultChecked={index === 0} className="peer sr-only" /><span className="flex cursor-pointer items-center gap-2 rounded-xl border border-border bg-background px-3 py-3 text-sm font-semibold transition peer-checked:border-primary peer-checked:bg-primary/5"><CreditCard className="size-4 text-primary" /> {method}</span></label>)}</div><p className="mt-3 flex items-center gap-2 text-xs text-muted-foreground"><CircleAlert className="size-3.5" /> Prototype : aucune somme ne sera débitée.</p></div><Button type="submit" className="mt-8 w-full sm:w-auto" data-testid="button-submit-order">Confirmer ma commande <ArrowRight className="size-4" /></Button></div><aside className="h-fit rounded-2xl bg-muted p-6"><p className="text-xs font-bold uppercase tracking-[.15em] text-primary">Votre panier</p><div className="mt-5 grid gap-3">{lines.map(({ product, quantity }) => <div key={product.id} className="flex justify-between gap-3 text-sm"><span>{quantity} × {product.name}</span><span className="font-bold">{formatFcfa((product.promotion ? product.price * (1 - product.promotion / 100) : product.price) * quantity)}</span></div>)}</div><div className="mt-5 border-t border-border pt-4 text-sm"><div className="flex justify-between"><span>Livraison</span><span>{formatFcfa(2000)}</span></div><div className="mt-3 flex justify-between text-base font-bold"><span>Total</span><span>{formatFcfa(total)}</span></div></div></aside></form></div></PublicShell>;
}

function Confirmation({ title, number, description, href, action }: { title: string; number: string; description: string; href: string; action: string }) {
  return <div className="mx-auto max-w-[720px] px-5 py-20 text-center lg:py-28"><span className="mx-auto grid size-20 place-items-center rounded-full bg-secondary text-secondary-foreground shadow-lg"><Check className="size-9" strokeWidth={2.5} /></span><p className="mt-8 text-xs font-bold uppercase tracking-[.18em] text-accent">C’est noté · {number}</p><h1 className="mt-3 font-display text-4xl font-bold tracking-tight">{title}</h1><p className="mx-auto mt-5 max-w-lg text-sm leading-7 text-muted-foreground">{description}</p><div className="mt-8 flex flex-col justify-center gap-3 sm:flex-row"><Link href={href} className="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground"> {action} <ArrowRight className="size-4" /></Link><Link href="/" className="inline-flex items-center justify-center rounded-xl border border-border px-5 py-3 text-sm font-bold">Retour à l’accueil</Link></div></div>;
}

function LocationPage() {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState('Toutes');
  const filtered = vehicles.filter((vehicle) => (category === 'Toutes' || vehicle.category === category) && `${vehicle.brand} ${vehicle.model} ${vehicle.category}`.toLowerCase().includes(query.toLowerCase()));
  return <PublicShell><div className="mx-auto max-w-[1240px] px-5 py-12 lg:px-8 lg:py-16"><PageIntro eyebrow="Mobilité à Dakar" title="Une voiture qui suit votre rythme." description="Réservez un véhicule propre, fiable et prêt à partir. La demande se fait en ligne, la confirmation avec notre équipe." action={<a href="https://wa.me/221772341860" target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-xl bg-secondary px-4 py-2.5 text-sm font-bold text-secondary-foreground"><MessageCircle className="size-4" /> Poser une question</a>} /><div className="mb-8 grid gap-3 md:grid-cols-[1fr_auto]"><label className="relative block"><Search className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Rechercher une marque, un modèle..." className="h-11 w-full rounded-xl border border-input bg-card pl-10 pr-4 text-sm outline-none focus:border-primary" data-testid="input-vehicle-search" /></label><select value={category} onChange={(event) => setCategory(event.target.value)} className="h-11 rounded-xl border border-input bg-card px-3 text-sm font-semibold outline-none" data-testid="select-vehicle-category"><option>Toutes</option>{Array.from(new Set(vehicles.map((vehicle) => vehicle.category))).map((item) => <option key={item}>{item}</option>)}</select></div>{filtered.length ? <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{filtered.map((vehicle, index) => <div key={vehicle.id} className={cx('animate-rise', `delay-${Math.min(index + 1, 5)}`)}><VehicleCard vehicle={vehicle} /></div>)}</div> : <EmptyState title="Aucun véhicule dans cette recherche" description="Modifiez vos filtres ou contactez-nous pour une solution sur mesure." icon={CarFront} />}</div></PublicShell>;
}

function VehiclePage() {
  const { id } = useParams<{ id: string }>(); const vehicle = getVehicle(id || ''); const [, setLocation] = useLocation(); const [gallery, setGallery] = useState(0);
  if (!vehicle) return <NotFound />;
  return <PublicShell><div className="mx-auto max-w-[1100px] px-5 py-10 lg:px-8 lg:py-16"><Link href="/location" className="mb-8 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-primary"><ArrowLeft className="size-4" /> Retour aux véhicules</Link><div className="grid gap-10 md:grid-cols-[1.1fr_.9fr]"><div><div className="overflow-hidden rounded-[2rem] border border-border"><Visual type={`${vehicle.images[gallery].replace('-1', '').replace('-2', '')}`} vehicle className="aspect-[1.1/1] w-full" /></div><div className="mt-3 grid grid-cols-2 gap-3">{vehicle.images.map((image, index) => <button key={image} onClick={() => setGallery(index)} className={cx('overflow-hidden rounded-xl border-2', gallery === index ? 'border-primary' : 'border-transparent')} data-testid={`button-gallery-${index}`}><Visual type={image.replace('-1', '').replace('-2', '')} vehicle className="h-24 w-full" /></button>)}</div></div><div><p className="text-xs font-bold uppercase tracking-[.17em] text-accent">{vehicle.category} · {vehicle.year}</p><h1 className="mt-3 font-display text-4xl font-bold tracking-tight">{vehicle.brand} {vehicle.model}</h1><p className="mt-4 text-sm leading-6 text-muted-foreground">Un véhicule suivi par notre équipe, contrôlé avant chaque départ et adapté aux trajets de Dakar comme aux escapades plus longues.</p><div className="mt-7 grid grid-cols-2 gap-2">{[['Places', `${vehicle.seats}`], ['Boîte', vehicle.transmission], ['Carburant', vehicle.fuel], ['Climatisation', vehicle.airConditioning ? 'Oui' : 'Non']].map(([key, value]) => <div key={key} className="rounded-xl bg-muted p-3"><p className="text-xs text-muted-foreground">{key}</p><p className="mt-1 text-sm font-bold">{value}</p></div>)}</div><div className="mt-8 flex items-end justify-between border-t border-border pt-6"><div><span className="font-display text-3xl font-bold">{formatFcfa(vehicle.pricePerDay)}</span><span className="text-sm text-muted-foreground"> / jour</span></div><span className="rounded-full bg-primary/10 px-3 py-1.5 text-xs font-bold text-primary">{vehicle.availability ? 'Disponible à la demande' : 'Actuellement réservé'}</span></div><Button onClick={() => setLocation(`/reservation?vehicle=${vehicle.id}`)} disabled={!vehicle.availability} className="mt-6 w-full py-3.5" data-testid="button-reserve-vehicle">{vehicle.availability ? <>Demander une réservation <ArrowRight className="size-4" /></> : 'Véhicule indisponible'}</Button><div className="mt-8 rounded-2xl border border-border p-5"><p className="font-display font-bold">Conditions de location</p><ul className="mt-4 grid gap-3 text-sm text-muted-foreground">{vehicle.conditions.map((condition) => <li key={condition} className="flex items-center gap-2"><Check className="size-4 text-primary" /> {condition}</li>)}</ul></div></div></div></div></PublicShell>;
}

function ReservationPage() {
  const params = new URLSearchParams(window.location.search); const initialVehicle = getVehicle(params.get('vehicle') || '') || vehicles.find((vehicle) => vehicle.availability); const { setRentals, setUser, user } = useApp(); const [done, setDone] = useState<string | null>(null);
  const [start, setStart] = useState(''); const [end, setEnd] = useState('');
  const days = start && end ? Math.max(1, Math.ceil((new Date(end).getTime() - new Date(start).getTime()) / 86400000)) : 1; const estimate = (initialVehicle?.pricePerDay || 0) * days;
  if (done) return <PublicShell><Confirmation title="Demande bien reçue" number={done} description="Notre équipe va vérifier les disponibilités et vous confirmer le départ par téléphone. Le prix affiché est une estimation, sans paiement en ligne." href="/location" action="Voir les autres véhicules" /></PublicShell>;
  if (!initialVehicle) return <PublicShell><div className="mx-auto max-w-[700px] px-5 py-20"><EmptyState title="Aucun véhicule sélectionné" description="Choisissez un véhicule dans notre parc avant de faire une demande." icon={CarFront} /></div></PublicShell>;
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const name = String(data.get('name')); const phone = String(data.get('phone')); const id = `LOC-${Math.floor(115 + Math.random() * 500)}`; setRentals((current) => [{ id, customer: name, phone, vehicleId: initialVehicle.id, start: String(data.get('start')), end: String(data.get('end')), pickup: String(data.get('pickup')), returnLocation: String(data.get('return')), total: estimate, status: 'À confirmer' }, ...current]); setUser({ name, phone, role: user.role || 'client' }); setDone(id); };
  return <PublicShell><div className="mx-auto max-w-[1100px] px-5 py-12 lg:px-8 lg:py-16"><PageIntro eyebrow="Réservation véhicule" title="Organisons votre départ." description="Donnez-nous les détails du trajet. La demande est gratuite et sera confirmée par notre équipe." /><form onSubmit={submit} className="grid gap-8 lg:grid-cols-[1fr_350px]"><div className="rounded-2xl border border-border bg-card p-5 sm:p-7"><div className="flex items-center gap-4 border-b border-border pb-6"><Visual type={initialVehicle.images[0].replace('-1', '')} vehicle className="size-20 rounded-xl" /><div><p className="text-xs font-bold uppercase tracking-[.14em] text-muted-foreground">Votre choix</p><h2 className="font-display text-xl font-bold">{initialVehicle.brand} {initialVehicle.model}</h2><p className="text-sm text-muted-foreground">{formatFcfa(initialVehicle.pricePerDay)} / jour</p></div></div><h2 className="mt-8 font-display text-xl font-bold">Dates et lieux</h2><div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Début" type="datetime-local" name="start" required value={start} onChange={(event) => setStart(event.target.value)} data-testid="input-rental-start" /><Field label="Retour" type="datetime-local" name="end" required value={end} onChange={(event) => setEnd(event.target.value)} data-testid="input-rental-end" /><SelectField label="Lieu de prise en charge" name="pickup" defaultValue="Agence Point E" className="sm:col-span-2" data-testid="select-rental-pickup"><option>Agence Point E</option><option>Aéroport Blaise Diagne</option><option>Livraison à Dakar (sur devis)</option></SelectField><SelectField label="Lieu de retour" name="return" defaultValue="Agence Point E" className="sm:col-span-2" data-testid="select-rental-return"><option>Agence Point E</option><option>Aéroport Blaise Diagne</option><option>Autre lieu (à préciser)</option></SelectField></div><h2 className="mt-9 border-t border-border pt-7 font-display text-xl font-bold">Vos coordonnées</h2><div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Nom complet" name="name" placeholder="Ex. Ibrahima Ba" required defaultValue={user.name} data-testid="input-rental-name" /><Field label="Téléphone" name="phone" placeholder="77 000 00 00" required defaultValue={user.phone} data-testid="input-rental-phone" /></div><Button type="submit" className="mt-8 w-full sm:w-auto" data-testid="button-submit-rental">Envoyer la demande <ArrowRight className="size-4" /></Button></div><aside className="h-fit rounded-2xl bg-primary p-6 text-primary-foreground"><p className="text-xs font-bold uppercase tracking-[.15em] text-secondary">Estimation</p><div className="mt-7 flex items-baseline justify-between"><span className="text-sm text-primary-foreground/70">{days} jour{days > 1 ? 's' : ''}</span><span className="font-display text-3xl font-bold">{formatFcfa(estimate)}</span></div><div className="mt-5 border-t border-primary-foreground/15 pt-4 text-sm text-primary-foreground/70"><p>Tarif journalier <span className="float-right">{formatFcfa(initialVehicle.pricePerDay)}</span></p><p className="mt-3">Caution <span className="float-right">Selon conditions</span></p></div><p className="mt-7 text-xs leading-5 text-primary-foreground/50">Le montant final sera validé par l’équipe selon les dates et le lieu de retour. Aucun paiement en ligne.</p></aside></form></div></PublicShell>;
}

function LoginPage() {
  const { setUser } = useApp(); const [, setLocation] = useLocation(); const [mode, setMode] = useState<'client' | 'admin'>('client');
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const name = String(data.get('name') || (mode === 'admin' ? 'Aminata Mbaye' : 'Visiteur')); const phone = String(data.get('phone') || '77 000 00 00'); setUser({ name, phone, role: mode }); setLocation(mode === 'admin' ? '/admin' : '/compte'); };
  const demoAccounts = [
    { role: 'client' as const, name: 'Awa Ndiaye', phone: '77 234 18 60', email: 'client.demo@tralogistique.sn', title: 'Compte client', description: 'Commandes, locations et historique' },
    { role: 'admin' as const, name: 'Aminata Mbaye', phone: '77 000 00 01', email: 'admin.demo@tralogistique.sn', title: 'Administration', description: 'Pilotage, produits et opérations' },
  ];
  const signInDemo = (account: typeof demoAccounts[number]) => { setUser({ name: account.name, phone: account.phone, role: account.role }); setLocation(account.role === 'admin' ? '/admin' : '/compte'); };
  return <div className="grid min-h-[100dvh] lg:grid-cols-[.85fr_1.15fr]"><div className="relative hidden overflow-hidden bg-primary p-10 text-primary-foreground lg:flex lg:flex-col lg:justify-between"><Logo dark /><div className="relative z-10 max-w-md"><p className="text-xs font-bold uppercase tracking-[.2em] text-secondary">TRALOGISTIQUE / ESPACE</p><h1 className="mt-5 font-display text-6xl font-bold leading-[.95] tracking-[-.05em]">Tout ce qui<br />fait avancer<br /><span className="text-secondary">Dakar.</span></h1><p className="mt-6 max-w-sm text-sm leading-6 text-primary-foreground/65">Un compte pour suivre vos commandes, vos réservations et vos prochains départs.</p></div><div className="relative z-10 flex items-center gap-3 text-sm text-primary-foreground/60"><span className="grid size-9 place-items-center rounded-full bg-secondary text-secondary-foreground"><ShieldCheckIcon /></span> Vos données restent sur cet appareil.</div><div className="absolute -bottom-20 -right-24 size-96 rounded-full border-[60px] border-secondary/15" /><div className="absolute right-12 top-32 size-36 rounded-full border-[24px] border-accent/20" /></div><div className="flex flex-col justify-center bg-background px-5 py-10 sm:px-12 lg:px-20"><div className="mx-auto w-full max-w-[420px]"><div className="lg:hidden"><Logo /></div><div className="mt-12 lg:mt-0"><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Bon retour</p><h2 className="mt-3 font-display text-4xl font-bold tracking-tight">Entrez dans votre espace.</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Prototype local : aucun compte réel n’est créé.</p></div><div className="mt-8 grid grid-cols-2 rounded-xl bg-muted p-1"><button onClick={() => setMode('client')} className={cx('rounded-lg py-2.5 text-sm font-bold transition', mode === 'client' ? 'bg-card text-primary shadow-sm' : 'text-muted-foreground')} data-testid="button-login-client">Client</button><button onClick={() => setMode('admin')} className={cx('rounded-lg py-2.5 text-sm font-bold transition', mode === 'admin' ? 'bg-card text-primary shadow-sm' : 'text-muted-foreground')} data-testid="button-login-admin">Propriétaire</button></div><div className="mt-5 grid gap-3"><p className="text-xs font-bold uppercase tracking-[.15em] text-muted-foreground">Accès démo · connexion en 1 clic</p>{demoAccounts.map((account) => <button key={account.role} type="button" onClick={() => signInDemo(account)} className="group flex items-center justify-between gap-4 rounded-2xl border border-border bg-card p-4 text-left transition hover:-translate-y-0.5 hover:border-primary/40 hover:shadow-sm" data-testid={`button-demo-${account.role}`}><span className="flex min-w-0 items-center gap-3"><span className={cx('grid size-10 shrink-0 place-items-center rounded-xl font-display font-bold', account.role === 'admin' ? 'bg-secondary text-secondary-foreground' : 'bg-primary/10 text-primary')}>{account.role === 'admin' ? 'A' : 'C'}</span><span className="min-w-0"><span className="block text-sm font-bold">{account.title}</span><span className="mt-0.5 block truncate text-xs text-muted-foreground">{account.email}</span><span className="mt-1 block text-xs text-muted-foreground">{account.description}</span></span></span><ArrowRight className="size-4 shrink-0 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-primary" /></button>)}</div><div className="my-6 flex items-center gap-3 text-[10px] font-bold uppercase tracking-[.16em] text-muted-foreground"><span className="h-px flex-1 bg-border" /> ou personnaliser <span className="h-px flex-1 bg-border" /></div><form onSubmit={submit} className="grid gap-4"><Field label="Votre nom" name="name" placeholder={mode === 'admin' ? 'Aminata Mbaye' : 'Awa Ndiaye'} required data-testid="input-login-name" /><Field label="Téléphone" name="phone" placeholder="77 000 00 00" required data-testid="input-login-phone" /><Button type="submit" className="mt-3 w-full py-3.5" data-testid="button-login-submit"><LogIn className="size-4" /> {mode === 'admin' ? 'Ouvrir le pilotage' : 'Accéder à mon espace'}</Button></form><p className="mt-6 text-center text-xs text-muted-foreground">Vous pouvez aussi <Link href="/" className="font-bold text-primary">continuer sans compte</Link>.</p></div></div></div>;
}
function ShieldCheckIcon() { return <Check className="size-4" />; }

function AccountPage() {
  const { user, orders, rentals, setUser } = useApp(); const [, setLocation] = useLocation(); const [tab, setTab] = useState('overview');
  if (!user.role) return <PublicShell><div className="mx-auto max-w-[680px] px-5 py-20"><EmptyState title="Votre espace vous attend" description="Connectez-vous pour retrouver vos commandes, vos locations et vos informations." icon={UserRound} /><div className="mt-5 text-center"><Link href="/connexion" className="inline-flex rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground">Se connecter</Link></div></div></PublicShell>;
  const tabs = [['overview', 'Vue d’ensemble'], ['orders', 'Mes commandes'], ['rentals', 'Mes locations'], ['settings', 'Paramètres']];
  return <PublicShell><div className="mx-auto max-w-[1100px] px-5 py-12 lg:px-8 lg:py-16"><div className="flex flex-col justify-between gap-6 border-b border-border pb-8 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Espace client</p><h1 className="mt-3 font-display text-4xl font-bold tracking-tight">Bonjour, {user.name.split(' ')[0] || 'vous'}.</h1><p className="mt-2 text-sm text-muted-foreground">Tout est au même endroit.</p></div><button onClick={() => { setUser({ name: '', phone: '', role: null }); setLocation('/'); }} className="inline-flex items-center gap-2 self-start text-sm font-bold text-muted-foreground hover:text-destructive md:self-auto"><LogOut className="size-4" /> Se déconnecter</button></div><div className="mt-7 flex gap-1 overflow-x-auto border-b border-border">{tabs.map(([id, label]) => <button key={id} onClick={() => setTab(id)} className={cx('whitespace-nowrap border-b-2 px-4 py-3 text-sm font-bold transition', tab === id ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground')} data-testid={`button-account-${id}`}>{label}</button>)}</div>{tab === 'overview' && <div className="mt-8 grid gap-5 md:grid-cols-3"><div className="rounded-2xl bg-primary p-6 text-primary-foreground md:col-span-2"><p className="text-xs font-bold uppercase tracking-[.16em] text-secondary">Votre activité</p><div className="mt-8 grid grid-cols-2 gap-5 sm:grid-cols-3"><div><p className="font-display text-3xl font-bold">{orders.filter((order) => order.phone === user.phone || order.customer === user.name).length}</p><p className="mt-1 text-xs text-primary-foreground/60">Commandes</p></div><div><p className="font-display text-3xl font-bold">{rentals.filter((rental) => rental.phone === user.phone || rental.customer === user.name).length}</p><p className="mt-1 text-xs text-primary-foreground/60">Locations</p></div><div><p className="font-display text-3xl font-bold">0</p><p className="mt-1 text-xs text-primary-foreground/60">Notifications</p></div></div></div><div className="rounded-2xl bg-secondary p-6"><Bell className="size-5 text-secondary-foreground" /><p className="mt-8 font-display text-xl font-bold">Tout est calme.</p><p className="mt-2 text-sm leading-6 text-secondary-foreground/70">Nous vous préviendrons ici dès qu’une commande bougera.</p></div><div className="rounded-2xl border border-border bg-card p-6 md:col-span-3"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">Dernières commandes</h2><button onClick={() => setTab('orders')} className="text-sm font-bold text-primary">Tout voir <ArrowRight className="ml-1 inline size-4" /></button></div><div className="mt-5 grid gap-3">{orders.slice(0, 2).map((order) => <OrderMini key={order.id} order={order} />)}</div></div></div>}{tab === 'orders' && <div className="mt-8 grid gap-3">{orders.length ? orders.map((order) => <OrderMini key={order.id} order={order} detailed />) : <EmptyState title="Pas encore de commande" description="Votre première sélection locale vous attend dans la boutique." icon={ShoppingBag} />}</div>}{tab === 'rentals' && <div className="mt-8 grid gap-3">{rentals.length ? rentals.map((rental) => <RentalMini key={rental.id} rental={rental} />) : <EmptyState title="Aucune location" description="Parcourez notre parc pour préparer votre prochain départ." icon={CarFront} />}</div>}{tab === 'settings' && <div className="mt-8 max-w-xl rounded-2xl border border-border bg-card p-6"><h2 className="font-display text-xl font-bold">Vos informations</h2><div className="mt-6 grid gap-4"><Field label="Nom complet" defaultValue={user.name} /><Field label="Téléphone" defaultValue={user.phone} /><Button onClick={() => setTab('overview')} className="mt-2 justify-self-start">Enregistrer localement</Button></div></div>}</div></PublicShell>;
}
function OrderMini({ order, detailed = false }: { order: Order; detailed?: boolean }) { return <div className="flex flex-col justify-between gap-4 rounded-xl border border-border bg-background p-4 sm:flex-row sm:items-center"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-secondary/30 text-primary"><Package className="size-5" /></span><div><p className="text-sm font-bold">{order.id} · {order.items[0]?.name}{order.items.length > 1 ? ` + ${order.items.length - 1}` : ''}</p><p className="mt-1 text-xs text-muted-foreground">{order.date} {detailed && ` · ${order.payment}`}</p></div></div><div className="flex items-center justify-between gap-5 sm:justify-end"><span className="rounded-full bg-primary/10 px-2.5 py-1 text-xs font-bold text-primary">{order.status}</span><span className="font-display font-bold">{formatFcfa(order.total)}</span></div></div>; }
function RentalMini({ rental }: { rental: Rental }) { const vehicle = getVehicle(rental.vehicleId); return <div className="flex flex-col justify-between gap-4 rounded-xl border border-border bg-card p-4 sm:flex-row sm:items-center"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-accent/10 text-accent"><CarFront className="size-5" /></span><div><p className="text-sm font-bold">{vehicle?.brand} {vehicle?.model} · {rental.id}</p><p className="mt-1 text-xs text-muted-foreground">{rental.start.replace('T', ' à ')} → {rental.end.replace('T', ' à ')}</p></div></div><span className="rounded-full bg-secondary/30 px-2.5 py-1 text-xs font-bold text-primary">{rental.status}</span></div>; }

function StatCard({ label, value, change, icon: Icon, accent = false }: { label: string; value: string; change?: string; icon: typeof Wallet; accent?: boolean }) { return <div className={cx('rounded-2xl border p-5', accent ? 'border-secondary/50 bg-secondary' : 'border-border bg-card')}><div className="flex items-start justify-between"><span className={cx('grid size-9 place-items-center rounded-xl', accent ? 'bg-secondary-foreground/10 text-secondary-foreground' : 'bg-muted text-primary')}><Icon className="size-[18px]" /></span>{change && <span className={cx('flex items-center gap-1 text-xs font-bold', accent ? 'text-secondary-foreground' : 'text-primary')}><TrendingUp className="size-3.5" /> {change}</span>}</div><p className={cx('mt-6 text-xs font-bold uppercase tracking-[.12em]', accent ? 'text-secondary-foreground/65' : 'text-muted-foreground')}>{label}</p><p className={cx('mt-1 font-display text-2xl font-bold', accent ? 'text-secondary-foreground' : 'text-foreground')}>{value}</p></div>; }

function AdminOverview() {
  const { orders, deliveries, rentals, customers } = useApp();
  const revenue = orders.reduce((sum, order) => sum + order.total, 0);
  const report = { generatedAt: new Date().toISOString(), orders, deliveries, rentals };
  return <AdminShell>
    <PageIntro eyebrow="Pilotage de l’activité" title="Bonjour Aminata." description="Les chiffres et les actions importantes de TRALOGISTIQUE, au même endroit." action={<div className="flex flex-wrap gap-2"><Link href="/admin/commandes" className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-bold hover:bg-muted"><ClipboardList className="size-4" /> Voir les commandes</Link><Button variant="soft" onClick={() => exportLocalFile('tralogistique-rapport.json', report)}><ArrowDown className="size-4" /> Exporter</Button></div>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Chiffre d’affaires" value={formatFcfa(revenue)} change="+12,4%" icon={Wallet} accent /><StatCard label="Commandes" value={String(orders.length)} change="+8,1%" icon={ShoppingBag} /><StatCard label="Livraisons actives" value={String(deliveries.filter((item) => item.status !== 'Livrée').length)} icon={Truck} /><StatCard label="Locations en cours" value={String(rentals.filter((item) => !['Terminée', 'Annulée'].includes(item.status)).length)} change="+2" icon={CarFront} /></div>
    <section className="mt-6 rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-accent">Centre d’action</p><h2 className="mt-2 font-display text-xl font-bold">Que voulez-vous gérer ?</h2><p className="mt-1 text-sm text-muted-foreground">Ouvrez directement le bon espace opérationnel.</p></div><CircleAlert className="size-5 text-accent" /></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Link href="/admin/produits" className="group rounded-xl bg-muted p-4 transition hover:-translate-y-0.5 hover:bg-secondary/30"><Package className="size-5 text-primary" /><span className="mt-5 block text-sm font-bold">Gérer les produits</span><span className="mt-1 block text-xs text-muted-foreground">Ajouter, modifier, retirer</span><ArrowUpRight className="mt-4 size-4 text-primary transition group-hover:translate-x-1" /></Link><Link href="/admin/commandes" className="group rounded-xl bg-muted p-4 transition hover:-translate-y-0.5 hover:bg-secondary/30"><ClipboardList className="size-5 text-primary" /><span className="mt-5 block text-sm font-bold">Traiter les commandes</span><span className="mt-1 block text-xs text-muted-foreground">Changer le statut</span><ArrowUpRight className="mt-4 size-4 text-primary transition group-hover:translate-x-1" /></Link><Link href="/admin/livraisons" className="group rounded-xl bg-muted p-4 transition hover:-translate-y-0.5 hover:bg-secondary/30"><Truck className="size-5 text-primary" /><span className="mt-5 block text-sm font-bold">Suivre les livraisons</span><span className="mt-1 block text-xs text-muted-foreground">Préparer, en route, livré</span><ArrowUpRight className="mt-4 size-4 text-primary transition group-hover:translate-x-1" /></Link><Link href="/admin/vehicules" className="group rounded-xl bg-muted p-4 transition hover:-translate-y-0.5 hover:bg-secondary/30"><CarFront className="size-5 text-primary" /><span className="mt-5 block text-sm font-bold">Gérer les véhicules</span><span className="mt-1 block text-xs text-muted-foreground">Parc et tarifs</span><ArrowUpRight className="mt-4 size-4 text-primary transition group-hover:translate-x-1" /></Link><Link href="/admin/promotions" className="group rounded-xl bg-muted p-4 transition hover:-translate-y-0.5 hover:bg-secondary/30"><Tag className="size-5 text-primary" /><span className="mt-5 block text-sm font-bold">Créer une promotion</span><span className="mt-1 block text-xs text-muted-foreground">Mettre un produit en avant</span><ArrowUpRight className="mt-4 size-4 text-primary transition group-hover:translate-x-1" /></Link></div></section>
    <div className="mt-6 grid gap-5 xl:grid-cols-[1.4fr_.8fr]"><div className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-bold">Flux de la semaine</h2><p className="mt-1 text-xs text-muted-foreground">Ventes boutique · activité récente</p></div><MoreHorizontal className="size-4 text-muted-foreground" /></div><div className="mt-8 flex h-48 items-end gap-2 sm:gap-4">{[46, 62, 42, 78, 58, 92, 70].map((height, index) => <div key={index} className="group flex flex-1 flex-col items-center gap-2"><div className="relative w-full"><div className={cx('mx-auto max-w-11 rounded-t-lg transition group-hover:bg-accent', index === 6 ? 'bg-secondary' : 'bg-primary/15')} style={{ height: `${height * 1.55}px` }} /><span className="absolute -top-6 left-1/2 -translate-x-1/2 text-[10px] font-bold opacity-0 transition group-hover:opacity-100">{height}k</span></div><span className="text-[10px] font-bold text-muted-foreground">{['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'][index]}</span></div>)}</div></div><div className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-bold">À traiter</h2><p className="mt-1 text-xs text-muted-foreground">Les prochaines actions</p></div><CircleAlert className="size-5 text-accent" /></div><div className="mt-7 grid gap-4"><Link href="/admin/commandes" className="flex items-center justify-between rounded-xl bg-muted p-3 transition hover:bg-secondary/30"><span className="flex items-center gap-3 text-sm font-semibold"><span className="grid size-8 place-items-center rounded-lg bg-card text-primary"><Package size={16} /></span>Commandes à préparer</span><span className="font-display font-bold text-primary">{orders.filter((item) => item.status === 'En préparation').length} <ArrowRight className="ml-1 inline size-3.5" /></span></Link><Link href="/admin/livraisons" className="flex items-center justify-between rounded-xl bg-muted p-3 transition hover:bg-secondary/30"><span className="flex items-center gap-3 text-sm font-semibold"><span className="grid size-8 place-items-center rounded-lg bg-card text-primary"><Truck size={16} /></span>Livraisons à suivre</span><span className="font-display font-bold text-primary">{deliveries.filter((item) => item.status !== 'Livrée').length} <ArrowRight className="ml-1 inline size-3.5" /></span></Link><Link href="/admin/locations" className="flex items-center justify-between rounded-xl bg-muted p-3 transition hover:bg-secondary/30"><span className="flex items-center gap-3 text-sm font-semibold"><span className="grid size-8 place-items-center rounded-lg bg-card text-primary"><CalendarDays size={16} /></span>Demandes de location</span><span className="font-display font-bold text-primary">{rentals.filter((item) => item.status === 'À confirmer').length} <ArrowRight className="ml-1 inline size-3.5" /></span></Link></div></div></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1fr_1fr]"><div className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">Activité récente</h2><Link href="/admin/commandes" className="text-sm font-bold text-primary">Tout voir</Link></div><div className="mt-5 grid gap-1">{orders.map((order) => <div key={order.id} className="flex items-center gap-3 border-b border-border py-3 last:border-0"><span className="grid size-8 place-items-center rounded-lg bg-muted text-primary"><Package className="size-4" /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{order.customer} <span className="font-normal text-muted-foreground">a passé une commande</span></p><p className="text-xs text-muted-foreground">{order.id} · {order.date}</p></div><span className="text-sm font-bold">{formatFcfa(order.total)}</span></div>)}</div></div><div className="rounded-2xl bg-primary p-6 text-primary-foreground"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-secondary">Base clients</p><h2 className="mt-3 font-display text-3xl font-bold">{customers.length}</h2><p className="mt-1 text-sm text-primary-foreground/60">clients enregistrés</p></div><Users className="size-6 text-secondary" /></div><div className="mt-10 flex items-center gap-3"><div className="flex -space-x-2"><span className="grid size-8 place-items-center rounded-full border-2 border-primary bg-accent text-xs font-bold">AN</span><span className="grid size-8 place-items-center rounded-full border-2 border-primary bg-secondary text-xs font-bold text-secondary-foreground">MF</span><span className="grid size-8 place-items-center rounded-full border-2 border-primary bg-[#9ab7a6] text-xs font-bold text-primary">FS</span></div><Link href="/admin/clients" className="text-xs font-bold text-secondary hover:underline">Ouvrir la base clients <ArrowRight className="ml-1 inline size-3.5" /></Link></div></div></div>
  </AdminShell>;
}

function AdminProducts() {
  const [location] = useLocation(); const [items, setItems] = usePersistentState<Product[]>('tralogistique-admin-products', products); const [query, setQuery] = useState(''); const [editing, setEditing] = useState<Product | null>(location.includes('new=1') ? { id: '', name: '', category: 'Épicerie', description: '', price: 0, unit: 'pièce', stock: 0, availability: true, image: 'grain' } : null);
  const filtered = items.filter((item) => `${item.name} ${item.category}`.toLowerCase().includes(query.toLowerCase()));
  const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const item: Product = { id: editing?.id || `product-${Date.now()}`, name: String(data.get('name')), category: String(data.get('category')), description: String(data.get('description') || 'Produit local sélectionné par l’équipe.'), price: Number(data.get('price')), unit: String(data.get('unit')), stock: Number(data.get('stock')), availability: data.get('availability') === 'on', promotion: Number(data.get('promotion')) || undefined, image: editing?.image || 'grain' }; setItems((current) => editing ? current.map((old) => old.id === editing.id ? item : old) : [item, ...current]); setEditing(null); };
   return <AdminShell><PageIntro eyebrow="Catalogue" title="Les produits." description="Maintenez le catalogue propre, disponible et lisible pour vos clients." action={<Button onClick={() => setEditing({ id: '', name: '', category: 'Épicerie', description: '', price: 0, unit: 'pièce', stock: 0, availability: true, image: 'grain' })} data-testid="button-add-product"><Plus className="size-4" /> Ajouter un produit</Button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Rechercher dans le catalogue..." className="h-11 w-full rounded-xl border border-input bg-card pl-10 pr-4 text-sm outline-none focus:border-primary" data-testid="input-admin-product-search" /></label><Button variant="outline"><Filter className="size-4" /> Filtres</Button></div><div className="overflow-hidden rounded-2xl border border-border bg-card"><div className="hidden grid-cols-[2fr_1fr_110px_120px_110px_100px] gap-4 border-b border-border px-5 py-3 text-[10px] font-bold uppercase tracking-[.14em] text-muted-foreground md:grid"><span>Produit</span><span>Catégorie</span><span>Prix</span><span>Stock</span><span>Statut</span><span>Actions</span></div>{filtered.map((item) => <div key={item.id} className="grid gap-3 border-b border-border p-4 last:border-0 md:grid-cols-[2fr_1fr_110px_120px_110px_100px] md:items-center md:gap-4 md:px-5"><div className="flex items-center gap-3"><Visual type={item.image} className="size-12 shrink-0 rounded-xl" /><div><p className="text-sm font-bold">{item.name}</p><p className="text-xs text-muted-foreground">{item.unit}</p></div></div><span className="text-sm text-muted-foreground">{item.category}</span><span className="text-sm font-bold">{formatFcfa(item.price)}</span><span className={cx('text-sm font-semibold', item.stock < 10 ? 'text-accent' : '')}>{item.stock} en stock</span><span className={cx('w-fit rounded-full px-2.5 py-1 text-[10px] font-bold', item.availability ? 'bg-primary/10 text-primary' : 'bg-muted text-muted-foreground')}>{item.availability ? 'Disponible' : 'Masqué'}</span><div className="flex flex-wrap gap-2"><button onClick={() => setEditing(item)} className="inline-flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-xs font-bold hover:bg-muted" aria-label={`Modifier ${item.name}`}><Pencil className="size-3.5" /> Modifier</button><button onClick={() => setItems((current) => current.filter((product) => product.id !== item.id))} className="inline-flex items-center gap-1.5 rounded-lg border border-destructive/20 px-2.5 py-1.5 text-xs font-bold text-destructive hover:bg-destructive/10" aria-label={`Supprimer ${item.name}`}><Trash2 className="size-3.5" /> Supprimer</button></div></div>)}</div>{editing && <Modal title={editing.id ? 'Modifier le produit' : 'Nouveau produit'} onClose={() => setEditing(null)}><form onSubmit={save} className="grid gap-4 sm:grid-cols-2"><Field label="Nom du produit" name="name" defaultValue={editing.name} required className="sm:col-span-2" /><SelectField label="Catégorie" name="category" defaultValue={editing.category}><option>Épicerie</option><option>Boissons</option><option>Snacking</option><option>Coffrets</option><option>Maison</option></SelectField><Field label="Prix (FCFA)" name="price" type="number" defaultValue={editing.price} required /><Field label="Unité" name="unit" defaultValue={editing.unit} required /><Field label="Stock" name="stock" type="number" defaultValue={editing.stock} required /><Field label="Promotion (%)" name="promotion" type="number" defaultValue={editing.promotion || ''} /><label className="flex items-center gap-2 pt-7 text-sm font-semibold"><input name="availability" type="checkbox" defaultChecked={editing.availability} className="size-4 accent-primary" /> Visible à la vente</label><label className="grid gap-2 text-sm font-semibold sm:col-span-2">Description<textarea name="description" defaultValue={editing.description} className="min-h-20 rounded-xl border border-input bg-background px-3 py-2 font-normal outline-none focus:border-primary" /></label><Button type="submit" className="sm:col-span-2">{editing.id ? 'Enregistrer les modifications' : 'Créer le produit'}</Button></form></Modal>}</AdminShell>;
}
function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-[60] grid place-items-center bg-foreground/35 p-4 backdrop-blur-sm animate-fade"><div className="max-h-[90dvh] w-full max-w-xl overflow-y-auto rounded-2xl border border-border bg-card p-6 shadow-2xl"><div className="mb-6 flex items-center justify-between"><h2 className="font-display text-xl font-bold">{title}</h2><button onClick={onClose} className="grid size-9 place-items-center rounded-lg hover:bg-muted" aria-label="Fermer"><X className="size-5" /></button></div>{children}</div></div>; }

function StatusSelect({ value, options, onChange }: { value: string; options: string[]; onChange: (value: string) => void }) { return <select value={value} onChange={(event) => onChange(event.target.value)} className="rounded-lg border border-input bg-background px-2.5 py-2 text-xs font-bold outline-none focus:border-primary">{options.map((option) => <option key={option}>{option}</option>)}</select>; }
function AdminOrders() {
  const { orders, setOrders } = useApp(); const [query, setQuery] = useState('');
  const filtered = orders.filter((order) => `${order.id} ${order.customer} ${order.phone}`.toLowerCase().includes(query.toLowerCase()));
  return <AdminShell><PageIntro eyebrow="Vente & préparation" title="Les commandes." description="Suivez chaque panier, du premier clic à la remise au livreur." /><div className="mb-5 flex gap-3"><label className="relative flex-1"><Search className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="N° de commande, client, téléphone..." className="h-11 w-full rounded-xl border border-input bg-card pl-10 pr-4 text-sm outline-none focus:border-primary" data-testid="input-admin-order-search" /></label><Button variant="outline"><ListFilter className="size-4" /> Filtrer</Button></div><div className="grid gap-3">{filtered.map((order) => <div key={order.id} className="rounded-2xl border border-border bg-card p-5"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div className="flex items-start gap-3"><span className="grid size-10 place-items-center rounded-xl bg-secondary/25 text-primary"><Package className="size-5" /></span><div><div className="flex flex-wrap items-center gap-2"><span className="font-display font-bold">{order.id}</span><span className="text-xs text-muted-foreground">{order.date}</span></div><p className="mt-1 text-sm">{order.customer} · {order.phone}</p></div></div><div className="flex items-center gap-3"><span className="font-display font-bold">{formatFcfa(order.total)}</span><StatusSelect value={order.status} options={['En préparation', 'En livraison', 'Livrée', 'Annulée']} onChange={(value) => setOrders((current) => current.map((item) => item.id === order.id ? { ...item, status: value } : item))} /></div></div><div className="mt-4 flex flex-col justify-between gap-3 border-t border-border pt-4 text-xs text-muted-foreground sm:flex-row"><span>{order.items.map((item) => `${item.quantity} × ${item.name}`).join(' · ')}</span><span className="flex items-center gap-1"><MapPin className="size-3.5" /> {order.address}, {order.neighborhood}</span></div></div>)}</div></AdminShell>;
}

function AdminDeliveries() {
  const { deliveries, setDeliveries } = useApp(); return <AdminShell><PageIntro eyebrow="Dernier kilomètre" title="Les livraisons." description="Une vue simple pour que chaque colis ait une prochaine étape." action={<Button variant="soft"><Truck className="size-4" /> Exporter</Button>} /><div className="grid gap-3">{deliveries.map((delivery) => <div key={delivery.id} className="rounded-2xl border border-border bg-card p-5"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div className="flex items-start gap-3"><span className={cx('grid size-10 place-items-center rounded-xl', delivery.status === 'Livrée' ? 'bg-primary/10 text-primary' : 'bg-accent/10 text-accent')}><Truck className="size-5" /></span><div><div className="flex items-center gap-2"><p className="font-display font-bold">{delivery.id}</p><span className="text-xs text-muted-foreground">Commande {delivery.orderId}</span></div><p className="mt-1 text-sm font-semibold">{delivery.customer} · {delivery.phone}</p></div></div><StatusSelect value={delivery.status} options={['À préparer', 'En route', 'Livrée', 'Incident']} onChange={(value) => setDeliveries((current) => current.map((item) => item.id === delivery.id ? { ...item, status: value } : item))} /></div><div className="mt-4 grid gap-3 border-t border-border pt-4 text-sm sm:grid-cols-3"><span className="flex items-center gap-2 text-muted-foreground"><MapPin className="size-4 text-primary" /> {delivery.address}</span><span className="flex items-center gap-2 text-muted-foreground"><Phone className="size-4 text-primary" /> {delivery.phone}</span><span className="flex items-center gap-2 text-muted-foreground"><Wallet className="size-4 text-primary" /> {formatFcfa(delivery.fee)}</span></div></div>)}</div></AdminShell>;
}

function AdminVehicles() {
  const [location] = useLocation(); const [items, setItems] = usePersistentState<Vehicle[]>('tralogistique-admin-vehicles', vehicles); const [editing, setEditing] = useState<Vehicle | null>(location.includes('new=1') ? { id: '', brand: '', model: '', year: 2025, category: 'Berline', seats: 5, transmission: 'Automatique', fuel: 'Essence', airConditioning: true, pricePerDay: 25000, conditions: [], availability: true, images: ['corolla-1', 'corolla-2'] } : null);
  const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const item: Vehicle = { id: editing?.id || `vehicle-${Date.now()}`, brand: String(data.get('brand')), model: String(data.get('model')), year: Number(data.get('year')), category: String(data.get('category')), seats: Number(data.get('seats')), transmission: String(data.get('transmission')), fuel: String(data.get('fuel')), airConditioning: data.get('air') === 'on', pricePerDay: Number(data.get('price')), conditions: editing?.conditions || ['Permis valide', 'Caution à confirmer'], availability: data.get('available') === 'on', images: editing?.images || ['corolla-1', 'corolla-2'] }; setItems((current) => editing ? current.map((old) => old.id === editing.id ? item : old) : [item, ...current]); setEditing(null); };
   return <AdminShell><PageIntro eyebrow="Parc automobile" title="Les véhicules." description="Disponibilité, tarifs et entretien : votre flotte en un coup d’œil." action={<Button onClick={() => setEditing({ id: '', brand: '', model: '', year: 2025, category: 'Berline', seats: 5, transmission: 'Automatique', fuel: 'Essence', airConditioning: true, pricePerDay: 25000, conditions: [], availability: true, images: ['corolla-1', 'corolla-2'] })}><Plus className="size-4" /> Ajouter un véhicule</Button>} /><div className="grid gap-4 md:grid-cols-2">{items.map((vehicle) => <div key={vehicle.id} className="overflow-hidden rounded-2xl border border-border bg-card"><div className="flex gap-4 p-4"><Visual type={vehicle.images[0].replace('-1', '')} vehicle className="h-28 w-36 shrink-0 rounded-xl" /><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><p className="text-xs font-bold uppercase tracking-[.13em] text-muted-foreground">{vehicle.category} · {vehicle.year}</p><h2 className="mt-1 font-display text-xl font-bold">{vehicle.brand} {vehicle.model}</h2></div><span className={cx('rounded-full px-2 py-1 text-[10px] font-bold', vehicle.availability ? 'bg-primary/10 text-primary' : 'bg-muted text-muted-foreground')}>{vehicle.availability ? 'Disponible' : 'Maintenance'}</span></div><p className="mt-4 font-display font-bold">{formatFcfa(vehicle.pricePerDay)} <span className="font-sans text-xs font-normal text-muted-foreground">/ jour</span></p></div></div><div className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-4 py-3"><span className="text-xs text-muted-foreground">{vehicle.seats} places · {vehicle.transmission} · {vehicle.fuel}</span><div className="flex flex-wrap gap-2"><button onClick={() => setEditing(vehicle)} className="inline-flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-xs font-bold hover:bg-muted" aria-label={`Modifier ${vehicle.model}`}><Pencil className="size-3.5" /> Modifier</button><button onClick={() => setItems((current) => current.filter((item) => item.id !== vehicle.id))} className="inline-flex items-center gap-1.5 rounded-lg border border-destructive/20 px-2.5 py-1.5 text-xs font-bold text-destructive hover:bg-destructive/10" aria-label={`Supprimer ${vehicle.model}`}><Trash2 className="size-3.5" /> Supprimer</button></div></div></div>)}</div>{editing && <Modal title={editing.id ? 'Modifier le véhicule' : 'Nouveau véhicule'} onClose={() => setEditing(null)}><form onSubmit={save} className="grid gap-4 sm:grid-cols-2"><Field label="Marque" name="brand" defaultValue={editing.brand} required /><Field label="Modèle" name="model" defaultValue={editing.model} required /><Field label="Année" name="year" type="number" defaultValue={editing.year} required /><SelectField label="Catégorie" name="category" defaultValue={editing.category}><option>Berline</option><option>Familiale</option><option>SUV</option><option>Utilitaire</option></SelectField><Field label="Places" name="seats" type="number" defaultValue={editing.seats} required /><SelectField label="Transmission" name="transmission" defaultValue={editing.transmission}><option>Automatique</option><option>Manuelle</option></SelectField><SelectField label="Carburant" name="fuel" defaultValue={editing.fuel}><option>Essence</option><option>Diesel</option><option>Hybride</option></SelectField><Field label="Prix / jour (FCFA)" name="price" type="number" defaultValue={editing.pricePerDay} required /><label className="flex items-center gap-2 pt-7 text-sm font-semibold"><input name="air" type="checkbox" defaultChecked={editing.airConditioning} className="size-4 accent-primary" /> Climatisation</label><label className="flex items-center gap-2 pt-7 text-sm font-semibold"><input name="available" type="checkbox" defaultChecked={editing.availability} className="size-4 accent-primary" /> Disponible</label><Button type="submit" className="sm:col-span-2">{editing.id ? 'Enregistrer' : 'Ajouter le véhicule'}</Button></form></Modal>}</AdminShell>;
}

function AdminRentals() {
  const { rentals, setRentals } = useApp(); return <AdminShell><PageIntro eyebrow="Mobilité" title="Les locations." description="Le calendrier opérationnel des départs, retours et demandes à confirmer." action={<Button variant="outline"><CalendarDays className="size-4" /> Vue calendrier</Button>} /><div className="mb-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><div className="rounded-xl border border-border bg-card p-4"><p className="text-xs text-muted-foreground">À confirmer</p><p className="mt-1 font-display text-2xl font-bold">{rentals.filter((rental) => rental.status === 'À confirmer').length + 2}</p></div><div className="rounded-xl border border-border bg-card p-4"><p className="text-xs text-muted-foreground">En cours</p><p className="mt-1 font-display text-2xl font-bold">3</p></div><div className="rounded-xl border border-border bg-card p-4"><p className="text-xs text-muted-foreground">Ce mois</p><p className="mt-1 font-display text-2xl font-bold">18</p></div><div className="rounded-xl border border-border bg-secondary p-4"><p className="text-xs text-secondary-foreground/70">Revenus location</p><p className="mt-1 font-display text-2xl font-bold text-secondary-foreground">{formatFcfa(482000)}</p></div></div><div className="grid gap-3">{rentals.map((rental) => { const vehicle = getVehicle(rental.vehicleId); return <div key={rental.id} className="rounded-2xl border border-border bg-card p-5"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div className="flex items-start gap-3"><span className="grid size-10 place-items-center rounded-xl bg-accent/10 text-accent"><CarFront className="size-5" /></span><div><div className="flex items-center gap-2"><p className="font-display font-bold">{rental.id}</p><span className="text-xs text-muted-foreground">{vehicle?.brand} {vehicle?.model}</span></div><p className="mt-1 text-sm">{rental.customer} · {rental.phone}</p></div></div><div className="flex items-center gap-3"><span className="font-display font-bold">{formatFcfa(rental.total)}</span><StatusSelect value={rental.status} options={['À confirmer', 'Confirmée', 'En cours', 'Terminée', 'Annulée']} onChange={(value) => setRentals((current) => current.map((item) => item.id === rental.id ? { ...item, status: value } : item))} /></div></div><div className="mt-4 grid gap-3 border-t border-border pt-4 text-sm sm:grid-cols-3"><span className="flex items-center gap-2 text-muted-foreground"><CalendarDays className="size-4 text-primary" /> {rental.start.replace('T', ' · ')}</span><span className="flex items-center gap-2 text-muted-foreground"><MapPin className="size-4 text-primary" /> {rental.pickup}</span><span className="flex items-center gap-2 text-muted-foreground"><ArrowRight className="size-4 text-primary" /> {rental.returnLocation}</span></div></div>; })}</div></AdminShell>;
}

function AdminClients() {
  const { customers } = useApp(); const [query, setQuery] = useState(''); const filtered = customers.filter((customer) => `${customer.name} ${customer.phone} ${customer.email}`.toLowerCase().includes(query.toLowerCase()));
  return <AdminShell><PageIntro eyebrow="Relation client" title="Les clients." description="Une base simple pour reconnaître les habitués et répondre plus vite." /><div className="mb-5"><label className="relative block max-w-lg"><Search className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Nom, téléphone ou email..." className="h-11 w-full rounded-xl border border-input bg-card pl-10 pr-4 text-sm outline-none focus:border-primary" data-testid="input-admin-client-search" /></label></div><div className="overflow-hidden rounded-2xl border border-border bg-card"><div className="hidden grid-cols-[1.4fr_1fr_1.4fr_100px_100px_90px] gap-4 border-b border-border px-5 py-3 text-[10px] font-bold uppercase tracking-[.14em] text-muted-foreground md:grid"><span>Client</span><span>Téléphone</span><span>Email</span><span>Commandes</span><span>Locations</span><span /></div>{filtered.map((customer) => <div key={customer.id} className="grid gap-3 border-b border-border p-4 last:border-0 md:grid-cols-[1.4fr_1fr_1.4fr_100px_100px_90px] md:items-center md:gap-4 md:px-5"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-full bg-secondary font-bold text-secondary-foreground">{customer.name.split(' ').map((name) => name[0]).join('').slice(0, 2)}</span><div><p className="text-sm font-bold">{customer.name}</p><p className="text-xs text-muted-foreground">{customer.address}</p></div></div><span className="text-sm text-muted-foreground">{customer.phone}</span><span className="text-sm text-muted-foreground">{customer.email}</span><span className="text-sm font-bold">{customer.orders}</span><span className="text-sm font-bold">{customer.rentals}</span><a href={`https://wa.me/221${customer.phone.replaceAll(' ', '')}`} target="_blank" rel="noreferrer" className="flex size-8 items-center justify-center rounded-lg bg-primary/10 text-primary" aria-label={`Contacter ${customer.name}`}><MessageCircle className="size-4" /></a></div>)}</div></AdminShell>;
}

function AdminPromotions() {
  const [location] = useLocation(); const { promotions, setPromotions } = useApp(); const [creating, setCreating] = useState(location.includes('new=1'));
  const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); setPromotions((current) => [{ id: `promo-${Date.now()}`, title: String(data.get('title')), productIds: [String(data.get('product'))], discount: Number(data.get('discount')), startsAt: String(data.get('startsAt')), endsAt: String(data.get('endsAt')), status: 'Active' }, ...current]); setCreating(false); };
  return <AdminShell><PageIntro eyebrow="Animation commerciale" title="Les promotions." description="Donnez de la visibilité aux bons produits, sans perdre le fil des dates." action={<Button onClick={() => setCreating(true)}><Plus className="size-4" /> Créer une promotion</Button>} /><div className="grid gap-4 md:grid-cols-2">{promotions.map((promotion) => <div key={promotion.id} className="rounded-2xl border border-border bg-card p-5"><div className="flex items-start justify-between"><span className="grid size-10 place-items-center rounded-xl bg-secondary/30 text-primary"><Tag className="size-5" /></span><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-bold text-primary">{promotion.status}</span></div><h2 className="mt-6 font-display text-xl font-bold">{promotion.title}</h2><p className="mt-2 text-sm text-muted-foreground">{promotion.productIds.map((id) => getProduct(id)?.name || id).join(' · ')}</p><div className="mt-6 flex items-end justify-between border-t border-border pt-4"><span className="font-display text-3xl font-bold text-accent">-{promotion.discount}%</span><span className="text-xs text-muted-foreground">{promotion.startsAt} → {promotion.endsAt}</span></div><button onClick={() => setPromotions((current) => current.filter((item) => item.id !== promotion.id))} className="mt-4 text-xs font-bold text-destructive">Supprimer la promotion</button></div>)}</div>{creating && <Modal title="Nouvelle promotion" onClose={() => setCreating(false)}><form onSubmit={save} className="grid gap-4"><Field label="Titre" name="title" placeholder="Ex. Week-end Teranga" required /><SelectField label="Produit concerné" name="product">{products.map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</SelectField><Field label="Remise (%)" name="discount" type="number" min="1" max="80" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Début" name="startsAt" type="date" required /><Field label="Fin" name="endsAt" type="date" required /></div><Button type="submit">Créer la promotion</Button></form></Modal>}</AdminShell>;
}

