function FutureServicePage() {
  const [location] = useLocation();
  const service = location.split('/').filter(Boolean).pop();
  const content = service === 'vente-vehicules'
    ? { eyebrow: 'À venir · mobilité', title: 'Acheter un véhicule avec le même niveau de clarté.', description: 'Nous préparons une sélection de véhicules contrôlés pour les familles, les professionnels et les projets qui avancent.', icon: CarFront, detail: 'Nous travaillons sur les critères, les contrôles et la présentation qui feront de cette offre un vrai achat accompagné.' }
    : service === 'pieces-rechange'
      ? { eyebrow: 'À venir · atelier', title: 'Les bonnes pièces, au bon moment.', description: 'Une future offre pour entretenir les véhicules du quotidien avec des références fiables et un stock suivi.', icon: Wrench, detail: 'La disponibilité, la compatibilité et le conseil seront au centre de ce service.' }
      : { eyebrow: 'En préparation · échanges', title: 'Ouvrir Dakar sur des routes bien préparées.', description: 'Notre activité import-export est en construction, avec une approche progressive et des partenaires sélectionnés.', icon: RouteIcon, detail: 'Nous préparons les flux, les formalités et les standards opérationnels avant d’ouvrir ce service.' };
  const Icon = content.icon;
  return <PublicShell><div className="mx-auto max-w-[1000px] px-5 py-12 lg:px-8 lg:py-20"><div className="max-w-3xl"><span className="grid size-14 place-items-center rounded-2xl bg-secondary text-secondary-foreground"><Icon className="size-7" /></span><p className="mt-8 text-xs font-bold uppercase tracking-[.2em] text-accent">{content.eyebrow}</p><h1 className="mt-4 font-display text-4xl font-bold leading-[1.02] tracking-tight sm:text-6xl">{content.title}</h1><p className="mt-6 max-w-2xl text-lg leading-8 text-muted-foreground">{content.description}</p></div><div className="mt-14 grid gap-4 md:grid-cols-[1.1fr_.9fr]"><div className="rounded-2xl bg-primary p-7 text-primary-foreground sm:p-9"><p className="font-mono text-xs font-bold tracking-[.16em] text-secondary">STATUT DU SERVICE</p><p className="mt-8 font-editorial text-4xl leading-none">Bientôt, mais pas à moitié.</p><p className="mt-6 text-sm leading-7 text-primary-foreground/65">{content.detail}</p></div><div className="rounded-2xl border border-border bg-card p-7"><p className="text-sm font-bold">Vous voulez être prévenu ?</p><p className="mt-2 text-sm leading-6 text-muted-foreground">Écrivez-nous avec votre besoin. Nous garderons votre demande sur cet appareil et notre équipe pourra vous répondre directement.</p><Link href="/contact" className="mt-8 inline-flex items-center gap-2 rounded-xl bg-secondary px-4 py-3 text-sm font-bold text-secondary-foreground">Nous contacter <ArrowRight className="size-4" /></Link></div></div><Link href="/" className="mt-10 inline-flex items-center gap-2 text-sm font-bold text-primary"><ArrowLeft className="size-4" /> Retour à l’accueil</Link></div></PublicShell>;
}

function NotFound() { return <PublicShell><div className="mx-auto max-w-[680px] px-5 py-24 text-center"><p className="font-display text-8xl font-bold text-secondary">404</p><h1 className="mt-5 font-display text-3xl font-bold">Cette route n’existe pas encore.</h1><p className="mt-3 text-sm text-muted-foreground">Revenez au début de l’itinéraire, on vous attend.</p><Link href="/" className="mt-7 inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground"><ArrowLeft className="size-4" /> Retour à l’accueil</Link></div></PublicShell>; }

function Router() {
  return <Switch>
    <Route path="/" component={HomePage} />
    <Route path="/boutique" component={BoutiquePage} />
    <Route path="/produit/:id" component={ProductPage} />
    <Route path="/panier" component={CartPage} />
    <Route path="/commande" component={CheckoutPage} />
     <Route path="/livraison" component={DeliveryPage} />
    <Route path="/location" component={LocationPage} />
    <Route path="/location/:id" component={VehiclePage} />
    <Route path="/reservation" component={ReservationPage} />
    <Route path="/connexion" component={LoginPage} />
    <Route path="/compte" component={AccountPage} />
     <Route path="/a-propos" component={AboutPage} />
     <Route path="/contact" component={ContactPage} />
     <Route path="/vente-vehicules" component={FutureServicePage} />
     <Route path="/pieces-rechange" component={FutureServicePage} />
     <Route path="/import-export" component={FutureServicePage} />
    <Route path="/admin" component={AdminOverview} />
    <Route path="/admin/produits" component={AdminProducts} />
    <Route path="/admin/commandes" component={AdminOrders} />
    <Route path="/admin/livraisons" component={AdminDeliveries} />
    <Route path="/admin/vehicules" component={AdminVehicles} />
    <Route path="/admin/locations" component={AdminRentals} />
    <Route path="/admin/clients" component={AdminClients} />
    <Route path="/admin/promotions" component={AdminPromotions} />
    <Route path="/admin/futur" component={FuturePage} />
    <Route component={NotFound} />
  </Switch>;
}

export default function App() {
  return <AppProvider><Router /></AppProvider>;
}